/**
 * @description : Nav Bar (Redesigned as modern vertical left sidebar)
 * @author : Bala krishna
 * @date : 16-01-2023
 * */
import React, { useContext, useEffect, useState } from 'react';
import {
  FaUniversity,
  FaCalendarAlt,
  FaBuilding,
  FaChalkboardTeacher,
  FaInfoCircle,
  FaUserTie,
  FaClipboardList,
  FaBookOpen,
  FaMoneyBill,
  FaBook,
  FaTshirt,
  FaBus,
  FaUserFriends,
  FaUserGraduate,
  FaUserCheck,
  FaChartBar,
  FaFileAlt,
  FaCog,
  FaUser,
  FaUserShield,
  FaRegLightbulb,
  FaChevronDown,
  FaChevronRight,
  FaHeadset,
} from 'react-icons/fa';
import { IoNotificationsSharp } from 'react-icons/io5';
import { HiInformationCircle } from 'react-icons/hi2';
import { PiUploadSimpleBold } from 'react-icons/pi';
import { Link, useLocation } from 'react-router-dom';
import { AuthContext } from '../../App';
import { isExactMatch } from '../../services/commonUtills/FormValidations';
import { RiDashboardFill } from 'react-icons/ri';
const getActiveNavModule = (pathname) => {
  if (!pathname || pathname === '/') {
    return 'dashboard';
  }
  if (pathname.startsWith('/dashboard')) {
    return 'dashboard';
  }
}
